# Experiment 3G: study hours versus math score with a fitted regression line.
source("r/Experiment-03/common.R"); library(ggplot2); d<-load_students(); p<-ggplot(d,aes(Hours_Studied,Math,label=Student))+geom_point(aes(colour=Math),size=3.5)+geom_smooth(method="lm",formula=y~x,se=TRUE,colour="#365F91",linetype="dashed")+geom_text(nudge_y=2,size=3,check_overlap=TRUE,show.legend=FALSE)+scale_colour_gradient(low="#E6A15A",high="#315B91")+labs(title="Study Hours vs Mathematics Score",x="Hours studied",y="Math score",colour="Math score")+theme_minimal(); ggsave(save_plot_path("3G_study_hours_regression.png"),p,width=8,height=5.5,dpi=180); print(p)
